INSERT INTO public.articles (slug, category, title_ar, title_en, summary_ar, summary_en, content_blocks, sources, reading_minutes, is_featured, is_published) VALUES ('foundations-of-tawhid', 'aqeedah', 'أصول العقيدة الإسلامية: التوحيد وأركان الإيمان الستة', 'Foundations of Islamic Creed: Tawhid and the Six Pillars of Faith', 'بيان مبسط ومؤصل لمعنى التوحيد الخالص وأقسامه، وأركان الإيمان الستة كما وردت في حديث جبريل عليه السلام.', 'A clear, source-grounded overview of pure monotheism (Tawhid) and the six articles of faith taught in Hadith Jibril.', '[{"type":"editorial","headingAr":"التوحيد أساس الرسالات السماوية","headingEn":"Tawhid: The Core of Every Prophetic Message","textAr":"العقيدة الإسلامية الصافية تبدأ من إفراد الله سبحانه وتعالى بالعبادة والطاعة، والإيمان الجازم بأنه الخالق المدبر لكل شؤون الكون، المتصف بصفات الكمال والجلال. ومن أصل التوحيد ينبثق سلام القلب واستقامة السلوك، إذ لا يتعلق المؤمن بغير ربه خوفاً ورجاءً وتوكلاً.","textEn":"Sound Islamic belief begins with devoting worship and obedience exclusively to Allah alone, recognizing Him as the Creator and Sustainer of the universe who possesses absolute perfection. From this certainty springs inner peace and moral clarity."},{"type":"quote","quoteType":"quran","arabicText":"﴿قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ﴾","englishText":"Say, ''He is Allah, [who is] One, Allah, the Eternal Refuge. He neither begets nor is born, nor is there to Him any equivalent.''","referenceAr":"سورة الإخلاص: الآيات 1-4","referenceEn":"Surah Al-Ikhlas 112:1-4"},{"type":"editorial","headingAr":"أركان الإيمان الستة","headingEn":"The Six Articles of Faith","textAr":"لخّص النبي ﷺ أصول الإيمان في حديث جبريل المشهور حين أجابه بقوله: أن تؤمن بالله وملائكته وكتبه ورسله واليوم الآخر وتؤمن بالقدر خيره وشره. فهذه الأركان الستة تمثل التصور الإيماني المتكامل الذي يربط الإنسان بخالقه ومصيره.","textEn":"Prophet Muhammad ﷺ summarized the articles of faith when asked by Angel Jibril: to believe in Allah, His angels, His revealed scriptures, His messengers, the Last Day, and divine decree (Al-Qadar), both its good and its testing aspects."},{"type":"quote","quoteType":"hadith","arabicText":"«أَنْ تُؤْمِنَ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ»","englishText":"It is to believe in Allah, His angels, His books, His messengers, the Last Day, and to believe in divine decree, its good and its evil.","referenceAr":"صحيح مسلم — حديث جبريل (رقم 8)","referenceEn":"Sahih Muslim — Hadith Jibril (#8)"}]'::jsonb, '[{"nameAr":"موقع سماحة الشيخ عبدالعزيز بن باز — دروس العقيدة","nameEn":"Official Website of Sheikh Bin Baz — Aqeedah Lessons","url":"https://binbaz.org.sa"},{"nameAr":"مجمع الملك فهد لطباعة المصحف الشريف — التفسير الميسر","nameEn":"King Fahd Complex — Al-Tafsir Al-Muyassar","url":"https://qurancomplex.gov.sa"}]'::jsonb, 5, TRUE, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, summary_ar = EXCLUDED.summary_ar, summary_en = EXCLUDED.summary_en, content_blocks = EXCLUDED.content_blocks, sources = EXCLUDED.sources, is_featured = EXCLUDED.is_featured, updated_at = NOW();
INSERT INTO public.articles (slug, category, title_ar, title_en, summary_ar, summary_en, content_blocks, sources, reading_minutes, is_featured, is_published) VALUES ('khushu-in-prayer', 'worship', 'الخشوع في الصلاة: روح العبادة وطمأنينة النفس', 'Khushu in Prayer: The Spirit of Worship and Inner Serenity', 'كيف يستحضر المسلم قلبه في صلاته اليومية من خلال استشعار معاني الفاتحة والتأني في الأركان.', 'Practical ways to cultivate presence of heart in daily Salah through unhurried stillness and reflection.', '[{"type":"editorial","headingAr":"الصلاة صلة بين العبد وربه","headingEn":"Prayer as a Direct Connection with Allah","textAr":"الصلاة عمود الدين وأول ما يُحاسب عليه العبد يوم القيامة. وقد جعلها الله قرة عينٍ للمؤمنين وملاذاً من هموم الدنيا. والخشوع فيها يعني سكون الجوارح وحضور القلب واستشعار الوقوف بين يدي الله تعالى.","textEn":"Salah is the pillar of Islam and a sanctuary from worldly anxiety. Khushu entails both outward tranquility of posture and inward presence of mind, recognizing that one is conversing directly with the Creator."},{"type":"quote","quoteType":"quran","arabicText":"﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ﴾","englishText":"Certainly will the believers have succeeded: They who are during their prayer humbly submissive.","referenceAr":"سورة المؤمنون: الآيتان 1-2","referenceEn":"Surah Al-Mu''minun 23:1-2"},{"type":"editorial","headingAr":"خطوات عملية لتحقيق الطمأنينة","headingEn":"Practical Steps Toward Tranquility","textAr":"من أعظم ما يعين على الخشوع: إسباغ الوضوء باحتساب الأجر، والتبكير إلى الصلاة أو التهيؤ لها قبل الأذان، وتدبر معاني سورة الفاتحة آيةً آية، والتأني في الركوع والسجود وعدم العجلة في التسبيح والأذكار.","textEn":"Key habits that nurture Khushu include performing Wudu mindfully, preparing calmly ahead of prayer time, reflecting on the verses of Surah Al-Fatihah, and pausing briefly in every bowing and prostration."}]'::jsonb, '[{"nameAr":"الرئاسة العامة للبحوث العلمية والإفتاء","nameEn":"Saudi General Presidency of Scholarly Research and Ifta","url":"https://www.alifta.gov.sa"}]'::jsonb, 4, TRUE, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, summary_ar = EXCLUDED.summary_ar, summary_en = EXCLUDED.summary_en, content_blocks = EXCLUDED.content_blocks, sources = EXCLUDED.sources, is_featured = EXCLUDED.is_featured, updated_at = NOW();
INSERT INTO public.articles (slug, category, title_ar, title_en, summary_ar, summary_en, content_blocks, sources, reading_minutes, is_featured, is_published) VALUES ('mercy-in-seerah', 'seerah', 'الرحمة والحكمة في سيرة النبي محمد ﷺ', 'Mercy and Wisdom in the Seerah of Prophet Muhammad ﷺ', 'قراءة في شمائل النبي ﷺ وهديه في التعامل مع أهله وأصحابه والمجتمع، وكيف غيّر العالم بالخلق العظيم.', 'Exploring the Prophet''s ﷺ compassion, patience, and leadership in Makkah and Madinah.', '[{"type":"editorial","headingAr":"رسالة رحمة للعالمين","headingEn":"A Mercy Sent to All Creation","textAr":"لم تكن بعثة النبي محمد ﷺ حدثاً تاريخياً عابراً، بل كانت إشراقة هدايةٍ ورحمةٍ شملت الإنسان والبيئة والمجتمع. فقد ربّى جيلاً على الصدق والأمانة والعدل والرفق حتى شهد له المخالف قبل الموافق بسمو خلقه.","textEn":"The mission of Prophet Muhammad ﷺ brought mercy, moral clarity, and dignity to humanity. Even before prophethood he was known as Al-Amin (the Trustworthy), and throughout his life he answered hardship with forbearance."},{"type":"quote","quoteType":"quran","arabicText":"﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ﴾","englishText":"And We have not sent you, [O Muhammad], except as a mercy to the worlds.","referenceAr":"سورة الأنبياء: الآية 107","referenceEn":"Surah Al-Anbiya 21:107"},{"type":"quote","quoteType":"hadith","arabicText":"«إِنَّمَا بُعِثْتُ لِأُتَمِّمَ صَالِحَ الْأَخْلَاقِ»","englishText":"Indeed, I was only sent to perfect righteous character.","referenceAr":"مسند أحمد (8952) — والأدب المفرد للبخاري (273)","referenceEn":"Musnad Ahmad 8952, Al-Adab Al-Mufrad 273"}]'::jsonb, '[{"nameAr":"الرحيق المختوم — المباركفوري","nameEn":"Ar-Raheeq Al-Makhtum (The Sealed Nectar)"},{"nameAr":"موقع الشيخ عبدالعزيز بن باز — السيرة والشمائل","nameEn":"Sheikh Bin Baz Official Archive — Prophetic Biography","url":"https://binbaz.org.sa"}]'::jsonb, 6, TRUE, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, summary_ar = EXCLUDED.summary_ar, summary_en = EXCLUDED.summary_en, content_blocks = EXCLUDED.content_blocks, sources = EXCLUDED.sources, is_featured = EXCLUDED.is_featured, updated_at = NOW();
INSERT INTO public.articles (slug, category, title_ar, title_en, summary_ar, summary_en, content_blocks, sources, reading_minutes, is_featured, is_published) VALUES ('prophets-steadfastness', 'prophets', 'قصص الأنبياء: دروس الصبر والتوكل من إبراهيم ويوسف عليهما السلام', 'Stories of the Prophets: Lessons of Patience from Ibrahim and Yusuf', 'تأملات إيمانية في دعوة الخليل إبراهيم عليه السلام، وصبر نبي الله يوسف عليه السلام ويقينه بتدبير الله.', 'Faith-building reflections from the trials, prayers, and unwavering trust of Prophets Ibrahim and Yusuf (peace be upon them).', '[{"type":"editorial","headingAr":"لماذا قص الله علينا أخبار الأنبياء؟","headingEn":"Why the Quran Narrates the Stories of the Prophets","textAr":"تأتي قصص الأنبياء في القرآن الكريم لتثبيت القلوب وتربية المؤمنين على سنن الله في الابتلاء والنصر. ففي قصة نبي الله إبراهيم عليه السلام نرى قوة الحجة ولين الخطاب واليقين الكامل بكفاية الله، وفي قصة يوسف عليه السلام نرى العفة والعفو عند المقدرة والثقة بأن مع العسر يسراً.","textEn":"The Quranic accounts of the Prophets serve to steady hearts and illuminate divine wisdom through every season of life. Prophet Ibrahim exemplifies sincere devotion and calm reasoning, while Prophet Yusuf embodies integrity, forgiveness, and serene patience."},{"type":"quote","quoteType":"quran","arabicText":"﴿لَقَدْ كَانَ فِي قَصَصِهِمْ عِبْرَةٌ لِّأُولِي الْأَلْبَابِ﴾","englishText":"There was certainly in their stories a lesson for those of understanding.","referenceAr":"سورة يوسف: الآية 111","referenceEn":"Surah Yusuf 12:111"}]'::jsonb, '[{"nameAr":"تفسير القرآن العظيم — الحافظ ابن كثير","nameEn":"Tafsir al-Quran al-Azim — Ibn Kathir"}]'::jsonb, 5, FALSE, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, summary_ar = EXCLUDED.summary_ar, summary_en = EXCLUDED.summary_en, content_blocks = EXCLUDED.content_blocks, sources = EXCLUDED.sources, is_featured = EXCLUDED.is_featured, updated_at = NOW();
INSERT INTO public.articles (slug, category, title_ar, title_en, summary_ar, summary_en, content_blocks, sources, reading_minutes, is_featured, is_published) VALUES ('islamic-ethics-daily-life', 'manners', 'الأخلاق الإسلامية: الصدق والأمانة وحفظ اللسان', 'Islamic Manners: Truthfulness, Trustworthiness, and Guarding the Tongue', 'كيف تترجم القيم الإيمانية إلى سلوك عملي في الأسرة والعمل والتعامل الرقمي المعاصر.', 'Translating faith into everyday integrity across family life, work ethics, and modern digital speech.', '[{"type":"editorial","headingAr":"ميزان الخلق الحسن","headingEn":"The Weight of Noble Character","textAr":"لا ينفصل الدين في الإسلام عن الخلق الحسن؛ فالمسلم الحق صادقٌ في حديثه، أمينٌ في عمله، رحيمٌ بأهله وجيرانه، متثبتٌ فيما ينقله أو يكتبه. وقد شمل الهدي النبوي آداب الكلام في الواقع وفي كل وسيلة تواصل.","textEn":"In Islam, devotion and character are inseparable. A sincere believer upholds honesty in speech, fairness in dealings, kindness to family and neighbors, and care before repeating or sharing words."},{"type":"quote","quoteType":"hadith","arabicText":"«مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ»","englishText":"Whoever believes in Allah and the Last Day should speak what is good or remain silent.","referenceAr":"صحيح البخاري (6018) وصحيح مسلم (47)","referenceEn":"Sahih al-Bukhari 6018, Sahih Muslim 47"}]'::jsonb, '[{"nameAr":"صحيح البخاري — كتاب الأدب","nameEn":"Sahih al-Bukhari — Book of Good Manners"}]'::jsonb, 4, FALSE, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, summary_ar = EXCLUDED.summary_ar, summary_en = EXCLUDED.summary_en, content_blocks = EXCLUDED.content_blocks, sources = EXCLUDED.sources, is_featured = EXCLUDED.is_featured, updated_at = NOW();
INSERT INTO public.articles (slug, category, title_ar, title_en, summary_ar, summary_en, content_blocks, sources, reading_minutes, is_featured, is_published) VALUES ('new-muslim-roadmap', 'new_muslims', 'دليل المسلم الجديد: خطواتك الأولى نحو الطمأنينة والعبادة', 'New Muslim Guide: Your First Steps in Faith and Daily Worship', 'خارطة طريق هادئة وعملية لمن اعتنق الإسلام حديثاً أو يتعرف على مبادئ الإسلام الأساسية.', 'A calm, encouraging step-by-step introduction to the Five Pillars, Wudu, and starting your daily prayers.', '[{"type":"editorial","headingAr":"مرحباً بك في رحاب الإسلام","headingEn":"Welcome to a Journey of Clarity and Peace","textAr":"الإسلام دين الفطرة واليسر، يقوم على علاقة مباشرة بين الإنسان وخالقه دون وسطاء. تبدأ الخطوة الأولى بالشهادتين: شهادة أن لا إله إلا الله وأن محمداً رسول الله، ثم التدرج الهادئ في تعلم الوضوء والصلاة وبناء الصلة بالقرآن الكريم.","textEn":"Islam is a faith of clarity, mercy, and ease built on a direct relationship between you and your Creator. Your journey starts with the Shahadah (testimony of faith), followed by learning Wudu and gradually establishing the five daily prayers at a steady, comfortable pace."},{"type":"quote","quoteType":"quran","arabicText":"﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾","englishText":"Allah intends for you ease and does not intend for you hardship.","referenceAr":"سورة البقرة: الآية 185","referenceEn":"Surah Al-Baqarah 2:185"},{"type":"editorial","headingAr":"خطوات عملية للأسبوع الأول","headingEn":"Practical Focus for Your First Week","textAr":"لا تشغل نفسك بكل التفاصيل دفعة واحدة: ابدأ بحفظ سورة الفاتحة وتعلم خطوات الوضوء، واستخدم صفحة مواقيت الصلاة لمعرفة أوقات الصلوات الخمس، واجعل لك ورداً يسيراً من الأذكار والقرآن المترجم المعاني.","textEn":"Avoid feeling overwhelmed by trying to learn everything on day one. Begin with Surah Al-Fatihah and the steps of Wudu, use our Prayer Times section to track the five daily prayers, and read a few verses daily with clear translation."}]'::jsonb, '[{"nameAr":"بوابة دار الإسلام للمسلمين الجدد","nameEn":"IslamHouse — New Muslims Resources","url":"https://islamhouse.com"},{"nameAr":"موسوعة القرآن العالمية (QuranEnc)","nameEn":"QuranEnc Translations","url":"https://quranenc.com"}]'::jsonb, 7, TRUE, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, summary_ar = EXCLUDED.summary_ar, summary_en = EXCLUDED.summary_en, content_blocks = EXCLUDED.content_blocks, sources = EXCLUDED.sources, is_featured = EXCLUDED.is_featured, updated_at = NOW();
INSERT INTO public.articles (slug, category, title_ar, title_en, summary_ar, summary_en, content_blocks, sources, reading_minutes, is_featured, is_published) VALUES ('nurturing-quran-home', 'education', 'التربية الإسلامية في البيت: بناء بيئة قرآنية مطمئنة', 'Islamic Education at Home: Cultivating a Quran-Centered Family', 'أسس تربوية رفيقة لغرس حب الله ورسوله ﷺ في قلوب الأبناء عبر القدوة والحوار.', 'Gentle, practical ways for parents and educators to nurture love for the Quran and Prophetic character at home.', '[{"type":"editorial","headingAr":"القدوة قبل التلقين","headingEn":"Leading by Living Example","textAr":"التربية الإسلامية الناجحة تقوم على المحبة والرحمة والقدوة الصالحة قبل التوجيه المباشر. حين يرى الأبناء هدوء الوالدين عند الصلاة، وحرصهما على الذكر والاستماع للقرآن، ينشأ في البيت مناخٌ من السكينة والانتماء الإيماني.","textEn":"Effective Islamic upbringing flourishes through warmth, patience, and consistent example. When children witness parents welcoming prayer calmly and listening to Quran recitation together, faith becomes a natural source of comfort."},{"type":"quote","quoteType":"hadith","arabicText":"«خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ»","englishText":"The best among you are those who learn the Quran and teach it.","referenceAr":"صحيح البخاري (5027)","referenceEn":"Sahih al-Bukhari 5027"}]'::jsonb, '[{"nameAr":"صحيح البخاري — كتاب فضائل القرآن","nameEn":"Sahih al-Bukhari — Virtues of the Quran"}]'::jsonb, 5, FALSE, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, summary_ar = EXCLUDED.summary_ar, summary_en = EXCLUDED.summary_en, content_blocks = EXCLUDED.content_blocks, sources = EXCLUDED.sources, is_featured = EXCLUDED.is_featured, updated_at = NOW();
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-1', 'beginner', 'quran', 'ما عدد سور القرآن الكريم؟', 'How many surahs (chapters) are in the Noble Quran?', '["110 سور","112 سورة","114 سورة","120 سورة"]'::jsonb, '["110 surahs","112 surahs","114 surahs","120 surahs"]'::jsonb, 2, 'يتكون القرآن الكريم من 114 سورة تبدأ بسورة الفاتحة وتختتم بسورة الناس.', 'The Noble Quran consists of 114 surahs, opening with Al-Fatihah and concluding with An-Nas.', 'المصحف الشريف — مجمع الملك فهد', 'The Noble Quran (114 Chapters)', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-2', 'beginner', 'quran', 'ما أطول سورة في القرآن الكريم؟', 'Which is the longest surah in the Noble Quran?', '["سورة آل عمران","سورة البقرة","سورة النساء","سورة الأعراف"]'::jsonb, '["Surah Ali ''Imran","Surah Al-Baqarah","Surah An-Nisa","Surah Al-A''raf"]'::jsonb, 1, 'سورة البقرة هي أطول سور القرآن الكريم وتضم 286 آية.', 'Surah Al-Baqarah is the longest surah in the Quran, containing 286 verses.', 'سورة البقرة (السورة رقم 2)', 'Surah Al-Baqarah (Chapter 2, 286 verses)', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-3', 'beginner', 'fiqh', 'كم عدد الصلوات المفروضة في اليوم والليلة؟', 'How many obligatory daily prayers are prescribed in Islam?', '["ثلاث صلوات","أربع صلوات","خمس صلوات","ست صلوات"]'::jsonb, '["Three prayers","Four prayers","Five prayers","Six prayers"]'::jsonb, 2, 'الصلوات المفروضة خمس في اليوم والليلة: الفجر والظهر والعصر والمغرب والعشاء.', 'Five daily prayers are obligatory: Fajr, Dhuhr, Asr, Maghrib, and Isha.', 'صحيح البخاري (349) وصحيح مسلم (162)', 'Sahih al-Bukhari 349, Sahih Muslim 162', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-4', 'beginner', 'seerah', 'في أي مدينة وُلد النبي محمد ﷺ؟', 'In which city was Prophet Muhammad ﷺ born?', '["المدينة المنورة","مكة المكرمة","الطائف","القدس"]'::jsonb, '["Madinah","Makkah","Taif","Jerusalem"]'::jsonb, 1, 'وُلد النبي محمد ﷺ في مكة المكرمة في عام الفيل.', 'Prophet Muhammad ﷺ was born in Makkah in the Year of the Elephant.', 'الرحيق المختوم — السيرة النبوية', 'Ar-Raheeq Al-Makhtum (Prophetic Biography)', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-5', 'beginner', 'aqeedah', 'من هو المَلَك الموكّل بنزول الوحي على الأنبياء عليهم السلام؟', 'Which angel was entrusted with conveying divine revelation to the Prophets?', '["ميكائيل عليه السلام","إسرافيل عليه السلام","جبريل عليه السلام","مالك عليه السلام"]'::jsonb, '["Mika''il","Israfil","Jibril (Gabriel)","Malik"]'::jsonb, 2, 'جبريل عليه السلام هو الروح الأمين الموكّل بتبليغ الوحي من الله إلى رسله.', 'Angel Jibril (Gabriel) is the Trustworthy Spirit who delivered revelation to Allah''s messengers.', 'سورة البقرة: 97 وسورة الشعراء: 193', 'Surah Al-Baqarah 2:97, Ash-Shu''ara 26:193', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-6', 'beginner', 'quran', 'ما السورة التي تُعرف بأم الكتاب والسبع المثاني؟', 'Which surah is known as Umm al-Kitab (Mother of the Book) and As-Sab'' al-Mathani?', '["سورة الإخلاص","سورة الفاتحة","سورة يس","سورة الملك"]'::jsonb, '["Surah Al-Ikhlas","Surah Al-Fatihah","Surah Ya-Sin","Surah Al-Mulk"]'::jsonb, 1, 'سورة الفاتحة هي أعظم سورة في القرآن وتُسمى أم الكتاب والسبع المثاني.', 'Surah Al-Fatihah is called Umm al-Kitab and the Seven Oft-Repeated Verses.', 'صحيح البخاري (4474)', 'Sahih al-Bukhari 4474', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-7', 'beginner', 'fiqh', 'ما الشهر الهجري الذي يُفرض فيه صيامه على المسلمين؟', 'During which Hijri month is obligatory fasting observed?', '["شعبان","رجب","رمضان","ذو الحجة"]'::jsonb, '["Sha''ban","Rajab","Ramadan","Dhul-Hijjah"]'::jsonb, 2, 'صيام شهر رمضان المبارك هو الركن الرابع من أركان الإسلام.', 'Fasting the month of Ramadan is the fourth pillar of Islam.', 'سورة البقرة: 185', 'Surah Al-Baqarah 2:185', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-8', 'beginner', 'prophets', 'من هو أول نبي وبشر خلقه الله تعالى؟', 'Who was the first human being and prophet created by Allah?', '["نوح عليه السلام","آدم عليه السلام","إدريس عليه السلام","إبراهيم عليه السلام"]'::jsonb, '["Nuh (Noah)","Adam","Idris","Ibrahim"]'::jsonb, 1, 'آدم عليه السلام هو أبو البشر وأول الأنبياء عليهم السلام.', 'Prophet Adam (peace be upon him) is the father of humanity and the first prophet.', 'سورة البقرة: 30-37', 'Surah Al-Baqarah 2:30-37', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-9', 'beginner', 'quran', 'ما السورة التي تعدل ثلث القرآن الكريم في الفضل؟', 'Which surah is equivalent in reward to one-third of the Quran?', '["سورة الكوثر","سورة الفلق","سورة الإخلاص","سورة العصر"]'::jsonb, '["Surah Al-Kawthar","Surah Al-Falaq","Surah Al-Ikhlas","Surah Al-Asr"]'::jsonb, 2, 'ثبت في الصحيحين أن سورة الإخلاص ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ تعدل ثلث القرآن.', 'Recorded in Bukhari and Muslim, Surah Al-Ikhlas equals one-third of the Quran in reward.', 'صحيح البخاري (5013) وصحيح مسلم (811)', 'Sahih al-Bukhari 5013, Sahih Muslim 811', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-10', 'beginner', 'hadith', 'بأي حديث افتتح الإمام البخاري صحيحه والإمام النووي الأربعين النووية؟', 'With which hadith did both Imam al-Bukhari and Imam an-Nawawi open their collections?', '["«الدين النصيحة»","«إنما الأعمال بالنيات»","«المسلم من سلم المسلمون من لسانه ويده»","«لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه»"]'::jsonb, '["Religion is sincere advice","Actions are judged by intentions","A Muslim is one from whose tongue and hand others are safe","None of you truly believes until he loves for his brother..."]'::jsonb, 1, 'حديث عمر بن الخطاب رضي الله عنه: «إنما الأعمال بالنيات» هو أول حديث في صحيح البخاري والأربعين النووية.', 'The hadith of Umar ibn al-Khattab ''Actions are judged by intentions'' opens both works.', 'صحيح البخاري (1) — الأربعون النووية (1)', 'Sahih al-Bukhari #1 — Nawawi''s 40 Hadith #1', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-11', 'beginner', 'seerah', 'من هو أول من آمن من الرجال بالنبي ﷺ وصديقه في الهجرة؟', 'Who was the first adult man to accept Islam and accompany the Prophet ﷺ in the Hijrah?', '["عمر بن الخطاب رضي الله عنه","أبو بكر الصديق رضي الله عنه","عثمان بن عفان رضي الله عنه","علي بن أبي طالب رضي الله عنه"]'::jsonb, '["Umar ibn al-Khattab","Abu Bakr as-Siddiq","Uthman ibn Affan","Ali ibn Abi Talib"]'::jsonb, 1, 'أبو بكر الصديق رضي الله عنه هو أول من آمن من الرجال ورفيق النبي ﷺ في غار ثور.', 'Abu Bakr as-Siddiq was the first adult male to embrace Islam and the Prophet''s ﷺ companion in the cave of Thawr.', 'سورة التوبة: 40 — صحيح البخاري (3653)', 'Surah At-Tawbah 9:40 — Sahih al-Bukhari 3653', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('beg-12', 'beginner', 'fiqh', 'ما النسبة المقررة في زكاة النقود وعروض التجارة إذا بلغت النصاب وحال عليها الحول؟', 'What is the standard Zakat rate on cash savings and trade assets held for one lunar year above Nisab?', '["1%","2.5%","5%","10%"]'::jsonb, '["1%","2.5%","5%","10%"]'::jsonb, 1, 'زكاة الأموال النقدية وعروض التجارة هي ربع العشر أي 2.5%.', 'Zakat on monetary wealth and trade goods is one-fortieth, i.e. 2.5%.', 'صحيح البخاري (1454) وسنن أبي داود (1572)', 'Sahih al-Bukhari 1454, Sunan Abi Dawud 1572', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-1', 'intermediate', 'quran', 'ما السورة الوحيدة في القرآن الكريم التي لا تبدأ بالبسملة؟', 'Which is the only surah in the Quran that does not begin with Bismillah?', '["سورة الأنفال","سورة التوبة","سورة النمل","سورة الفجر"]'::jsonb, '["Surah Al-Anfal","Surah At-Tawbah","Surah An-Naml","Surah Al-Fajr"]'::jsonb, 1, 'سورة التوبة هي السورة الوحيدة التي لم تُفتتح بالبسملة، بينما وردت البسملة مرتين في سورة النمل (في أولها وفي الآية 30).', 'Surah At-Tawbah is the only chapter without a Bismillah at its opening, whereas Bismillah appears twice in Surah An-Naml.', 'سورة التوبة (السورة رقم 9)', 'Surah At-Tawbah (Chapter 9)', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-2', 'intermediate', 'quran', 'ما أعظم آية في كتاب الله تعالى؟', 'Which verse did the Prophet ﷺ identify as the greatest verse in the Quran?', '["آية الدين","آية الكرسي","خواتيم سورة البقرة","آية النور"]'::jsonb, '["Ayat ad-Dayn (2:282)","Ayat al-Kursi (2:255)","Last verses of Al-Baqarah","Ayat an-Nur (24:35)"]'::jsonb, 1, 'أقرّ النبي ﷺ أُبي بن كعب رضي الله عنه بأن أعظم آية في كتاب الله هي آية الكرسي (البقرة: 255).', 'Prophet Muhammad ﷺ affirmed to Ubayy ibn Ka''b that Ayat al-Kursi (2:255) is the greatest verse in the Quran.', 'صحيح مسلم (810)', 'Sahih Muslim 810', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-3', 'intermediate', 'seerah', 'كم سنة استمرت الدعوة النبوية في مكة المكرمة قبل الهجرة إلى المدينة؟', 'Approximately how many years did the Makkan period of Prophethood last before the Hijrah?', '["10 سنوات","13 سنة","15 سنة","23 سنة"]'::jsonb, '["10 years","13 years","15 years","23 years"]'::jsonb, 1, 'بُعث النبي ﷺ وعمره أربعون سنة، وأقام بمكة ثلاث عشرة سنة ثم هاجر إلى المدينة وأقام بها عشر سنوات.', 'The Prophet ﷺ remained in Makkah for 13 years after revelation began, then spent 10 years in Madinah (23 years total).', 'صحيح البخاري (3851) وصحيح مسلم (2351)', 'Sahih al-Bukhari 3851, Sahih Muslim 2351', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-4', 'intermediate', 'prophets', 'من هم أولو العزم من الرسل الخمسة المذكورون في القرآن الكريم؟', 'Who are the five ''Ulul-Azm (Messengers of Firm Resolve)?', '["آدم وإدريس وهود وصالح وشعيب","نوح وإبراهيم وموسى وعيسى ومحمد عليهم السلام","إبراهيم وإسماعيل وإسحاق ويعقوب ويوسف","داود وسليمان وأيوب ويونس وزكريا"]'::jsonb, '["Adam, Idris, Hud, Salih, Shu''ayb","Nuh, Ibrahim, Musa, Isa, and Muhammad (peace be upon them)","Ibrahim, Ismail, Ishaq, Yaqub, Yusuf","Dawud, Sulaiman, Ayyub, Yunus, Zakariyya"]'::jsonb, 1, 'أولو العزم من الرسل خمسة جمعهم الله في سورة الأحزاب وسورة الشورى: نوح وإبراهيم وموسى وعيسى ومحمد عليهم الصلاة والسلام.', 'The five Ulul-Azm named together in Surah Al-Ahzab (33:7) and Ash-Shura (42:13) are Nuh, Ibrahim, Musa, Isa, and Muhammad.', 'سورة الأحزاب: 7 وسورة الشورى: 13', 'Surah Al-Ahzab 33:7, Ash-Shura 42:13', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-5', 'intermediate', 'hadith', 'من الصحابي الملقب بـ «حفظة حديث النبي» والأكثر روايةً للحديث النبوي؟', 'Which Companion narrated the largest number of Prophetic hadiths?', '["أنس بن مالك","عبدالله بن عمر","أبو هريرة رضي الله عنه","عبدالله بن عباس"]'::jsonb, '["Anas ibn Malik","Abdullah ibn Umar","Abu Hurayrah","Abdullah ibn Abbas"]'::jsonb, 2, 'أبو هريرة عبدالرحمن بن صخر الدوسي رضي الله عنه هو أكثر الصحابة رواية للحديث، وقد دعا له النبي ﷺ بالحفظ.', 'Abu Hurayrah (may Allah be pleased with him) is the most prolific narrator of Hadith among the Companions.', 'صحيح البخاري (118)', 'Sahih al-Bukhari 118', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-6', 'intermediate', 'fiqh', 'ما مقدار النِّصاب من الذهب الخالص (عيار 24) لوجوب الزكاة؟', 'What is the Nisab threshold for pure gold (24K) in Zakat?', '["50 جراماً","85 جراماً","120 جراماً","595 جراماً"]'::jsonb, '["50 grams","85 grams","120 grams","595 grams"]'::jsonb, 1, 'نصاب الذهب عشرون مثقالاً، ويعادل نحو 85 جراماً من الذهب الخالص، بينما نصاب الفضة 595 جراماً.', 'Gold Nisab is 20 mithqals (approximately 85 grams of pure gold), whereas silver Nisab is 595 grams.', 'قرارات المجامع الفقهية — وهيئة كبار العلماء', 'Fiqh Academy Consensus on Nisab Weights', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-7', 'intermediate', 'seerah', 'ما الغزوة التي كانت في السنة الثانية من الهجرة وسماها القرآن الكريم «يوم الفرقان»؟', 'Which battle in 2 AH did the Quran refer to as ''Yawm al-Furqan'' (Day of Criterion)?', '["غزوة أُحد","غزوة بدر الكبرى","غزوة الأحزاب","غزوة خيبر"]'::jsonb, '["Battle of Uhud","Battle of Badr","Battle of the Trench","Battle of Khaybar"]'::jsonb, 1, 'وقعت غزوة بدر الكبرى في السابع عشر من رمضان في السنة الثانية للهجرة.', 'The Battle of Badr took place in Ramadan of the 2nd year after Hijrah.', 'سورة الأنفال: الآية 41', 'Surah Al-Anfal 8:41', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-8', 'intermediate', 'quran', 'ما آخر سورة أُنزلت كاملة من القرآن الكريم وفق المشهور عند أهل العلم؟', 'Which complete surah is widely reported by scholars to have been the last revealed in full?', '["سورة الفلق","سورة الكوثر","سورة النصر","سورة العلق"]'::jsonb, '["Surah Al-Falaq","Surah Al-Kawthar","Surah An-Nasr","Surah Al-Alaq"]'::jsonb, 2, 'روى مسلم عن ابن عباس رضي الله عنهما أن آخر سورة أُنزلت جميعاً هي سورة النصر ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾.', 'Ibn Abbas reported in Sahih Muslim that Surah An-Nasr (110) was the last complete surah revealed.', 'صحيح مسلم (3024)', 'Sahih Muslim 3024', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-9', 'intermediate', 'prophets', 'في أي سورة وردت قصة نبي الله موسى عليه السلام والعبد الصالح الخضر؟', 'In which surah is the story of Prophet Musa and Al-Khidr narrated?', '["سورة طه","سورة القصص","سورة الكهف","سورة الأنبياء"]'::jsonb, '["Surah Ta-Ha","Surah Al-Qasas","Surah Al-Kahf","Surah Al-Anbiya"]'::jsonb, 2, 'وردت قصة موسى عليه السلام مع الخضر في سورة الكهف من الآية 60 إلى الآية 82.', 'The journey of Musa with Al-Khidr is detailed in Surah Al-Kahf (18:60-82).', 'سورة الكهف: الآيات 60-82', 'Surah Al-Kahf 18:60-82', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-10', 'intermediate', 'aqeedah', 'ما معنى «الإحسان» كما عرّفه النبي ﷺ في حديث جبريل؟', 'How did Prophet Muhammad ﷺ define ''Ihsan'' in Hadith Jibril?', '["إطعام الطعام وإفشاء السلام","أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك","كثرة الصدقة في السر والعلن","الصوم والقيام في شهر رمضان"]'::jsonb, '["Feeding the poor and spreading peace","To worship Allah as though you see Him, and if you do not see Him, know that He sees you","Giving abundant charity in secret and open","Fasting and praying at night in Ramadan"]'::jsonb, 1, 'الإحسان هو استحضار مراقبة الله تعالى وإتقان العبادة: «أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك».', 'Ihsan is worshipping Allah with total awareness of His presence and sight.', 'صحيح البخاري (50) وصحيح مسلم (8)', 'Sahih al-Bukhari 50, Sahih Muslim 8', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-11', 'intermediate', 'hadith', 'ماذا يُقصد بمصطلح «متفق عليه» عند المحدّثين؟', 'What does the grading ''Muttafaqun Alayh'' (Agreed Upon) signify in Hadith sciences?', '["أجمع عليه الفقهاء الأربعة","أخرجه الإمامان البخاري ومسلم في صحيحيهما","رواه أكثر من عشرة صحابة","ورد في السنن الأربعة كلها"]'::jsonb, '["Agreed upon by the four legal schools","Recorded by both Imam al-Bukhari and Imam Muslim in their Sahihs","Narrated by over ten Companions","Recorded in all four Sunan collections"]'::jsonb, 1, 'إذا قيل «متفق عليه» فالمقصود اتفاق الإمامين البخاري ومسلم على تخريج الحديث في صحيحيهما.', 'In Hadith terminology, Muttafaqun Alayh means both Sahih al-Bukhari and Sahih Muslim include the hadith.', 'علوم الحديث — مصطلح الحديث', 'Hadith Terminology (Mustalah al-Hadith)', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('int-12', 'intermediate', 'fiqh', 'ما هي «الأيام البيض» التي يُستحب صيامها من كل شهر هجري؟', 'Which three days of each Hijri month are known as Al-Ayyam al-Bid (the White Days)?', '["الأول والثاني والثالث","الثالث عشر والرابع عشر والخامس عشر","العشرون والحادي والعشرون والثاني والعشرون","الثامن والعشرون والتاسع والعشرون والثلاثون"]'::jsonb, '["1st, 2nd, and 3rd","13th, 14th, and 15th","20th, 21st, and 22nd","28th, 29th, and 30th"]'::jsonb, 1, 'الأيام البيض هي أيام 13 و14 و15 من كل شهر قمري لابيضاض لياليها بتمام البدر.', 'They are the 13th, 14th, and 15th of each lunar month when the moon is full.', 'سنن النسائي (2422) والترمذي (761)', 'Sunan an-Nasa''i 2422, Al-Tirmidhi 761', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-1', 'advanced', 'quran', 'كم عدد أجزاء القرآن الكريم، وكم عدد السجدات (سجدات التلاوة) المشهورة في رواية حفص؟', 'How many Juz does the Quran have, and how many prostrations of recitation (Sajdat at-Tilawah) are in the Hafs Mushaf?', '["30 جزءاً و12 سجدة","30 جزءاً و15 سجدة","30 جزءاً و10 سجدات","60 جزءاً و15 سجدة"]'::jsonb, '["30 Juz and 12 prostrations","30 Juz and 15 prostrations","30 Juz and 10 prostrations","60 Juz and 15 prostrations"]'::jsonb, 1, 'ينقسم المصحف الشريف إلى 30 جزءاً، وفي مصحف المدينة برواية حفص عن عاصم 15 موضعاً لسجود التلاوة.', 'The Quran is divided into 30 Juz, and the Madinah Mushaf (Hafs) marks 15 places of Sajdat at-Tilawah.', 'مصحف المدينة المنورة — مجمع الملك فهد', 'Madinah Mushaf (King Fahd Complex)', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-2', 'advanced', 'hadith', 'كم عدد الأحاديث في متن «الأربعين النووية» كما أتمه الإمام النووي رحمه الله قبل أن يضيف ابن رجب؟', 'Exactly how many hadiths did Imam an-Nawawi compile in his original Al-Arba''in an-Nawawiyyah?', '["40 حديثاً","42 حديثاً","45 حديثاً","50 حديثاً"]'::jsonb, '["40 hadiths","42 hadiths","45 hadiths","50 hadiths"]'::jsonb, 1, 'بلغت أحاديث الأربعين النووية 42 حديثاً، ثم أتمّها الحافظ ابن رجب الحنبلي إلى 50 في كتابه جامع العلوم والحكم.', 'Imam an-Nawawi actually included 42 hadiths (later expanded to 50 by Ibn Rajab in Jami'' al-''Ulum wal-Hikam).', 'الأربعون النووية للإمام النووي', 'Al-Arba''in an-Nawawiyyah', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-3', 'advanced', 'quran', 'في أي سورتين من القرآن الكريم وردت كل الحروف الهجائية العربية الـ 28؟', 'Which two surahs in the Quran contain every single one of the 28 Arabic letters?', '["البقرة والكهف","آل عمران (الآية 154) والفتح (الآية 29)","يوسف ومريم","النساء والمائدة"]'::jsonb, '["Al-Baqarah and Al-Kahf","Ali ''Imran (verse 154) and Al-Fath (verse 29)","Yusuf and Maryam","An-Nisa and Al-Ma''idah"]'::jsonb, 1, 'اشتهرت الآية 154 من سورة آل عمران والآية 29 من سورة الفتح باشتمال كلٍّ منهما على حروف الهجاء العربية كلها.', 'Verses 3:154 (Ali ''Imran) and 48:29 (Al-Fath) are renowned for containing all 28 letters of the Arabic alphabet.', 'علوم القرآن — الإتقان في علوم القرآن للسيوطي', 'Al-Itqan fi ''Ulum al-Quran — Al-Suyuti', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-4', 'advanced', 'seerah', 'في أي عام هجري وقع صلح الحديبية؟', 'In which Hijri year did the Treaty of Hudaybiyyah take place?', '["السنة الرابعة للهجرة","السنة الخامسة للهجرة","السنة السادسة للهجرة","السنة الثامنة للهجرة"]'::jsonb, '["4 AH","5 AH","6 AH","8 AH"]'::jsonb, 2, 'وقع صلح الحديبية في شهر ذي القعدة من السنة السادسة للهجرة، وقد سماه الله فتحاً مبيناً في سورة الفتح.', 'The Treaty of Hudaybiyyah occurred in Dhul-Qi''dah of 6 AH, described in Surah Al-Fath as a manifest victory.', 'سورة الفتح: 1 — صحيح البخاري (2731)', 'Surah Al-Fath 48:1 — Sahih al-Bukhari 2731', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-5', 'advanced', 'aqeedah', 'ما الأسماء الثلاثة المتصلة في فاتحة سورة التوحيد والقرآن وآخر سورة الحشر الدالة على التنزيه المطلق؟', 'Which trio of Divine Names appears sequentially in Surah Al-Hashr (59:23) signifying absolute purity and peace?', '["الأول، الآخر، الظاهر","الملك، القدوس، السلام","الرحمن، الرحيم، الغفور","الخالق، البارئ، المصور"]'::jsonb, '["Al-Awwal, Al-Akhir, Az-Zahir","Al-Malik, Al-Quddus, As-Salam","Ar-Rahman, Ar-Rahim, Al-Ghafur","Al-Khaliq, Al-Bari'', Al-Musawwir"]'::jsonb, 1, 'في الآية 23 من سورة الحشر: ﴿هُوَ اللَّهُ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلَامُ الْمُؤْمِنُ الْمُهَيْمِنُ...﴾.', 'Surah Al-Hashr 59:23 sequences Al-Malik, Al-Quddus, and As-Salam consecutively.', 'سورة الحشر: الآية 23', 'Surah Al-Hashr 59:23', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-6', 'advanced', 'fiqh', 'ما حكم قضاء الصلوات المفروضة على الحائض بعد طهرها بالإجماع؟', 'By scholarly consensus, is a woman required to make up daily prayers missed during menstruation?', '["تقضي الصلاة ولا تقضي الصوم","تقضي الصوم ولا تقضي الصلاة","تقضي كليهما","لا تقضي أياً منهما"]'::jsonb, '["Makes up prayer, not fasting","Makes up fasting, not prayer","Makes up both","Makes up neither"]'::jsonb, 1, 'ثبت عن أم المؤمنين عائشة رضي الله عنها في الصحيحين: «كنا نُؤمر بقضاء الصوم ولا نُؤمر بقضاء الصلاة».', 'Aishah (may Allah be pleased with her) stated in Sahih Muslim: ''We were commanded to make up the fasts, and were not commanded to make up the prayers.''', 'صحيح البخاري (321) وصحيح مسلم (335)', 'Sahih al-Bukhari 321, Sahih Muslim 335', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-7', 'advanced', 'prophets', 'أي نبي من الأنبياء سأل ربه أن يشركه أخاه هارون في أمره ليشد به أزره؟', 'Which prophet asked Allah to appoint his brother Harun as a helper in his mission?', '["داود عليه السلام","موسى عليه السلام","سليمان عليه السلام","زكريا عليه السلام"]'::jsonb, '["Dawud","Musa (Moses)","Sulaiman","Zakariyya"]'::jsonb, 1, 'دعا نبي الله موسى عليه السلام ربه قائلاً: ﴿وَاجْعَل لِّي وَزِيرًا مِّنْ أَهْلِي ۝ هَارُونَ أَخِي ۝ اشْدُدْ بِهِ أَزْرِي﴾.', 'Prophet Musa prayed in Surah Ta-Ha (20:29-32) for Harun to share his task and strengthen him.', 'سورة طه: الآيات 29-32', 'Surah Ta-Ha 20:29-32', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-8', 'advanced', 'hadith', 'ما أول كتاب صنفه الإمام مالك بن أنس رحمه الله في الحديث والفقه؟', 'What is the landmark early compilation of Hadith and Fiqh authored by Imam Malik ibn Anas?', '["المسند","الموطأ","الأم","السنن الكبرى"]'::jsonb, '["Al-Musnad","Al-Muwatta","Al-Umm","As-Sunan al-Kubra"]'::jsonb, 1, '«الموطأ» هو كتاب الإمام مالك بن أنس إمام دار الهجرة، ويُعد من أقدم دواوين السنة المصنفة المرتبة على الأبواب الفقهية.', 'Al-Muwatta by Imam Malik is one of the earliest surviving thematic collections of Prophetic traditions and Madinan legal precedent.', 'موطأ الإمام مالك — دار الهجرة', 'Al-Muwatta of Imam Malik', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-9', 'advanced', 'quran', 'ما السورة التي ذكر فيها اسم الله «جل جلاله» في كل آية من آياتها؟', 'Which surah mentions the Name of Allah in every single one of its verses?', '["سورة الملك","سورة المجادلة","سورة الإخلاص","سورة النبأ"]'::jsonb, '["Surah Al-Mulk","Surah Al-Mujadila","Surah Al-Ikhlas","Surah An-Naba"]'::jsonb, 1, 'سورة المجادلة (السورة رقم 58، وعدد آياتها 22 آية) تفرّدت بذكر لفظ الجلالة «الله» في كل آية من آياتها.', 'Surah Al-Mujadila (Chapter 58, 22 verses) uniquely contains the Divine Name ''Allah'' in every verse.', 'سورة المجادلة: الآيات 1-22', 'Surah Al-Mujadila 58:1-22', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-10', 'advanced', 'seerah', 'من الصحابي الجليل الذي أشار بحفر الخندق حول المدينة في غزوة الأحزاب (السنة الخامسة للهجرة)؟', 'Which Companion proposed digging the defensive trench around Madinah during the Battle of the Confederates (5 AH)?', '["أبو عبيدة بن الجراح","سلمان الفارسي رضي الله عنه","خالد بن الوليد","سعد بن معاذ"]'::jsonb, '["Abu Ubaydah ibn al-Jarrah","Salman al-Farisi","Khalid ibn al-Walid","Sa''d ibn Mu''adh"]'::jsonb, 1, 'أشار سلمان الفارسي رضي الله عنه على النبي ﷺ بحفر الخندق في الجهة المكشوفة من المدينة.', 'Salman al-Farisi (may Allah be pleased with him) suggested digging the trench along Madinah''s exposed northern approach.', 'الرحيق المختوم — غزوة الأحزاب', 'Ar-Raheeq Al-Makhtum — Battle of the Trench', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-11', 'advanced', 'fiqh', 'في أي شهر هجري فُرضت زكاة الفطر وفي أي سنة من الهجرة شُرعت؟', 'In which Hijri year was Zakat al-Fitr legislated alongside the fast of Ramadan?', '["السنة الأولى للهجرة","السنة الثانية للهجرة","السنة الرابعة للهجرة","السنة الثامنة للهجرة"]'::jsonb, '["1 AH","2 AH","4 AH","8 AH"]'::jsonb, 1, 'فُرضت زكاة الفطر في السنة الثانية من الهجرة، وهو نفس العام الذي فُرض فيه صيام رمضان.', 'Zakat al-Fitr was prescribed in 2 AH, the same year Ramadan fasting became obligatory.', 'صحيح البخاري (1503) وصحيح مسلم (984)', 'Sahih al-Bukhari 1503, Sahih Muslim 984', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.quiz_questions (id, difficulty, category, question_ar, question_en, options_ar, options_en, correct_index, explanation_ar, explanation_en, reference_ar, reference_en, is_active) VALUES ('adv-12', 'advanced', 'aqeedah', 'ما الكلمتان الخفيفتان على اللسان، الثقيلتان في الميزان، الحبيبتان إلى الرحمن اللتان خُتم بهما صحيح البخاري؟', 'Which two phrases — light on the tongue, heavy on the Scale, beloved to the Most Merciful — conclude Sahih al-Bukhari?', '["لا إله إلا الله، والله أكبر","سبحان الله وبحمده، سبحان الله العظيم","الحمد لله، وأستغفر الله","لا حول ولا قوة إلا بالله، وحسبنا الله"]'::jsonb, '["La ilaha illallah, Allahu Akbar","SubhanAllahi wa bihamdihi, SubhanAllahil-Azim","Alhamdulillah, Astaghfirullah","La hawla wa la quwwata illa billah"]'::jsonb, 1, 'ختم الإمام البخاري جامعه الصحيح بحديث أبي هريرة: «كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم».', 'Imam al-Bukhari concluded his Sahih (#7563) with: ''SubhanAllahi wa bihamdihi, SubhanAllahil-Azim.''', 'صحيح البخاري — آخر حديث في الكتاب (7563)', 'Sahih al-Bukhari #7563 (Final Hadith)', TRUE) ON CONFLICT (id) DO UPDATE SET difficulty = EXCLUDED.difficulty, question_ar = EXCLUDED.question_ar, question_en = EXCLUDED.question_en, options_ar = EXCLUDED.options_ar, options_en = EXCLUDED.options_en, correct_index = EXCLUDED.correct_index, explanation_ar = EXCLUDED.explanation_ar, explanation_en = EXCLUDED.explanation_en, reference_ar = EXCLUDED.reference_ar, reference_en = EXCLUDED.reference_en;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('binbaz-official', 'scholarly', 'الموقع الرسمي لسماحة الشيخ عبدالعزيز بن باز', 'Official Website of Sheikh Abdulaziz bin Baz', 'أرشيف علمي موثوق للفتاوى والدروس والشروح الصوتية والكتب والمقالات في العقيدة والفقه والتفسير والحديث.', 'Verified scholarly archive of fatwas, lectures, books, and audio commentaries by Grand Mufti Sheikh Abdulaziz bin Baz.', 'https://binbaz.org.sa', 'مؤسسة عبدالعزيز بن باز الخيرية', 'Abdulaziz Bin Baz Charitable Foundation', ARRAY['ar']::text[], 10, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('alifta-official', 'fatwa', 'الرئاسة العامة للبحوث العلمية والإفتاء', 'General Presidency of Scholarly Research and Ifta (Saudi Arabia)', 'البوابة الرسمية لفتاوى اللجنة الدائمة للبحوث العلمية والإفتاء ومجلة البحوث الإسلامية.', 'Official portal of the Permanent Committee for Scholarly Research and Ifta in the Kingdom of Saudi Arabia.', 'https://www.alifta.gov.sa', 'المملكة العربية السعودية — الإفتاء', 'Saudi General Presidency of Ifta', ARRAY['ar', 'en', 'fr', 'ur']::text[], 20, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('quran-complex', 'quran_official', 'مجمع الملك فهد لطباعة المصحف الشريف', 'King Fahd Glorious Quran Printing Complex', 'المرجع العالمي المعتمد لطباعة المصحف الشريف، وترجمات معاني القرآن الكريم، والتفسير الميسر.', 'The premier authority in Madinah for Quran printing, Uthmani text verification, and vetted translations.', 'https://qurancomplex.gov.sa', 'المدينة المنورة — مجمع الملك فهد', 'King Fahd Complex, Madinah', ARRAY['ar', 'en', 'multi']::text[], 30, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('quranenc', 'multilingual', 'موسوعة القرآن الكريم (QuranEnc)', 'QuranEnc — Multilingual Quran Encyclopedia', 'ترجمات موثقة ومراجعة لمعاني القرآن الكريم بأكثر من 70 لغة عالمية.', 'Free, vetted translations of the meanings of the Noble Quran in over 70 world languages.', 'https://quranenc.com', 'موسوعة القرآن العالمية', 'IslamHouse / QuranEnc Project', ARRAY['ar', 'en', 'fr', 'es', 'id', 'ur', 'tr']::text[], 40, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('islamhouse', 'multilingual', 'موقع دار الإسلام (IslamHouse) متعدد اللغات', 'IslamHouse Multilingual Educational Portal', 'مكتبة دعوية شاملة للكتب والمرئيات والمواد التعريفية بالإسلام بأكثر من 100 لغة.', 'Comprehensive repository of authenticated books, articles, and guides about Islam in over 100 languages.', 'https://islamhouse.com', 'المكتب التعاوني للدعوة بالربوة', 'IslamHouse International', ARRAY['ar', 'en', 'multi']::text[], 50, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('ehsan-charity', 'charity', 'منصة إحسان الوطنية للعمل الخيري', 'Ehsan — National Platform for Charitable Work', 'المنصة الوطنية السعودية الرسمية الموثوقة لإخراج الزكاة والصدقات والكفارات والأضاحي والفرص الخيرية بإشراف الجهات الرسمية.', 'Saudi Arabia''s official national charity platform overseen by government authorities for Zakat, Sadaqah, and verified humanitarian causes.', 'https://ehsan.sa', 'الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا)', 'Official Saudi National Platform (ehsan.sa)', ARRAY['ar', 'en']::text[], 60, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('jood-eskan', 'charity', 'منصة جود الإسكان الخيرية', 'Jood Eskan Housing Charity Platform', 'منصة سعودية رسمية موثوقة تهدف إلى إشراك المجتمع في دعم الأسر الأشد حاجة لتوفير المسكن الملائم.', 'Official Saudi housing charity initiative connecting verified contributions directly to families in housing need.', 'https://joodeskan.sa', 'مؤسسة الإسكان التنموي الأهلية (سكن)', 'Sakan Developmental Housing Foundation', ARRAY['ar']::text[], 70, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.scholarly_resources (slug, category, title_ar, title_en, description_ar, description_en, url, organization_ar, organization_en, language_tags, sort_order, is_active) VALUES ('shefa-charity', 'charity', 'منصة شفاء الخيرية للعلاج', 'Shefa Medical Charity Platform', 'منصة رسمية تابعة لوزارة الصحة وصندوق الوقف الصحي لتغطية تكاليف علاج المرضى غير القادرين.', 'Official medical charity platform supporting treatment for patients in need under the Health Endowment Fund.', 'https://shefa.sa', 'صندوق الوقف الصحي — المملكة العربية السعودية', 'Health Endowment Fund, Saudi Arabia', ARRAY['ar']::text[], 80, TRUE) ON CONFLICT (slug) DO UPDATE SET title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, description_ar = EXCLUDED.description_ar, description_en = EXCLUDED.description_en, url = EXCLUDED.url;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('tawhid', 'التوحيد', 'Tawhid (Islamic Monotheism)', 'At-Tawhid', 'إفراد الله سبحانه وتعالى بالربوبية والألوهية والأسماء والصفات، وهو أصل دين الإسلام وأساس قبول الأعمال.', 'Affirming the absolute Oneness of Allah in Lordship, Worship, and His Names and Attributes — the foundational pillar of Islam.', 'aqeedah', 'سورة الإخلاص: 1-4', 'Surah Al-Ikhlas 112:1-4') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('sunnah', 'السنة النبوية', 'The Prophetic Sunnah', 'As-Sunnah', 'كل ما أُثر عن النبي محمد ﷺ من قولٍ أو فعلٍ أو تقريرٍ أو صفة، وهي المصدر الثاني للتشريع بعد القرآن الكريم.', 'The documented sayings, actions, tacit approvals, and noble character of Prophet Muhammad ﷺ, serving as the second primary source of Islamic guidance after the Quran.', 'hadith', 'سورة الحشر: 7', 'Surah Al-Hashr 59:7') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('fiqh', 'الفقه', 'Fiqh (Islamic Jurisprudence)', 'Al-Fiqh', 'العلم بالأحكام الشرعية العملية المكتسب من أدلتها التفصيلية في القرآن الكريم والسنة النبوية.', 'Understanding practical Islamic rulings derived from their detailed textual evidences in the Quran and Sunnah.', 'worship', 'صحيح البخاري: 71', 'Sahih al-Bukhari 71') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('dhikr', 'الذكر', 'Dhikr (Remembrance of Allah)', 'Adh-Dhikr', 'استحضار عظمة الله في القلب والثناء عليه باللسان بالتسبيح والتحميد والتهليل والتكبير وتلاوة القرآن والدعاء.', 'Remembering Allah with heart and tongue through glorification, praise, supplication, and Quran recitation.', 'worship', 'سورة الرعد: 28', 'Surah Ar-Ra''d 13:28') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('zakat-nisab', 'النِّصاب في الزكاة', 'Nisab (Zakat Threshold)', 'An-Nisab', 'الحد الأدنى من المال الذي إذا ملكه المسلم وحال عليه الحول الهجري وجبت فيه الزكاة، ويُقدّر بـ 85 جراماً من الذهب الخالص أو 595 جراماً من الفضة.', 'The minimum threshold of wealth (equivalent to 85g of pure gold or 595g of silver) held for one full lunar year upon which Zakat becomes obligatory.', 'fiqh', 'الفتاوى الشرعية — هيئة كبار العلماء', 'Scholarly Consensus on Zakat Thresholds') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('khatmah', 'الختمة', 'Khatmah (Complete Quran Reading)', 'Khatmah', 'إتمام قراءة القرآن الكريم كاملاً من سورة الفاتحة إلى سورة الناس بتدبر وترتيل.', 'Completing the recitation of the entire Holy Quran from Surah Al-Fatihah through Surah An-Nas with reflection.', 'quran', NULL, NULL) ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('makki-madani', 'المكي والمدني', 'Makki and Madani Surahs', 'Al-Makki wal-Madani', 'المكي ما نزل من القرآن قبل الهجرة النبوية إلى المدينة غالباً، والمدني ما نزل بعدها؛ ويمتاز المكي بترسيخ العقيدة والمدني بتفصيل الأحكام.', 'Makki chapters were revealed prior to the Hijrah (migration to Madinah), focusing on faith and Tawhid; Madani chapters followed the Hijrah, detailing legislation and community life.', 'quran', NULL, NULL) ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('ihsan', 'الإحسان', 'Ihsan (Spiritual Excellence)', 'Al-Ihsan', 'أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك؛ وهو أعلى مراتب الدين في الإخلاص والإتقان.', 'To worship Allah as though you see Him, and knowing that even if you do not see Him, He sees you — the pinnacle of sincerity and excellence.', 'aqeedah', 'حديث جبريل — صحيح مسلم: 8', 'Hadith Jibril — Sahih Muslim 8') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('hijri-calendar', 'التقويم الهجري', 'Hijri (Islamic Lunar) Calendar', 'At-Taqwim al-Hijri', 'التقويم القمري الإسلامي المؤرخ بهجرة النبي ﷺ من مكة إلى المدينة، ويتكون من اثني عشر شهراً قمرياً.', 'The Islamic lunar calendar anchored to Prophet Muhammad''s ﷺ migration (Hijrah) to Madinah, comprising 12 lunar months.', 'calendar', 'سورة التوبة: 36', 'Surah At-Tawbah 9:36') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
INSERT INTO public.glossary_terms (slug, term_ar, term_en, transliteration, definition_ar, definition_en, category, reference_ar, reference_en) VALUES ('sadaqah-jariyah', 'الصدقة الجارية', 'Sadaqah Jariyah (Ongoing Charity)', 'Sadaqah Jariyah', 'العمل الصالح والإنفاق الذي يستمر نفعه وثوابه بعد موت الإنسان، كالوقف والعلم النافع وسقيا الماء.', 'Enduring acts of charity whose benefit and reward continue even after one''s lifetime, such as endowments, water wells, and beneficial knowledge.', 'worship', 'صحيح مسلم: 1631', 'Sahih Muslim 1631') ON CONFLICT (slug) DO UPDATE SET term_ar = EXCLUDED.term_ar, term_en = EXCLUDED.term_en, definition_ar = EXCLUDED.definition_ar, definition_en = EXCLUDED.definition_en;
